#include "hb.hh"

#include <cairo.h>

#ifdef HB_NO_OPEN
#define hb_blob_create_from_file(x)  hb_blob_get_empty ()
#endif

#if !defined(HB_NO_COLOR) && defined(CAIRO_HAS_SVG_SURFACE)

#include "hb-ot.h"

#include "hb-ft.h"

